import { readFile } from 'node:fs/promises';

const root = new URL('../', import.meta.url);

export async function createBrowserBundle() {
  const modules = ['parser', 'renderer', 'examples', 'block-model', 'blocks', 'layout', 'app'];
  const source = (await Promise.all(modules.map(async name => {
    const content = await readFile(new URL(`src/${name}.js`, root), 'utf8');
    return content.replace(/^import .+;\n/gm, '').replace(/^export /gm, '');
  }))).join('\n');
  // A classic script avoids the CORS restrictions on file:// module imports.
  // Waiting for the DOM also supports the inline version in the document head.
  return `// Generated by npm run build. Edit src/ files, then rebuild.\n(() => {\n'use strict';\nconst start = () => {\n${source}\n};\nif (document.readyState === 'loading') {\n  document.addEventListener('DOMContentLoaded', start, { once: true });\n} else {\n  start();\n}\n})();\n`;
}

export async function createStructuresBundle() {
  const modules = ['structures-model', 'structures-renderer', 'structures'];
  const source = (await Promise.all(modules.map(async name =>
    (await readFile(new URL(`src/${name}.js`, root), 'utf8')).replace(/^import .+;\n/gm, '').replace(/^export /gm, '')
  ))).join('\n');
  return `// Generated by npm run build. Edit src/ files, then rebuild.\n(() => {\n'use strict';\n${source}\n})();\n`;
}
